import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
a = [int(x) for x in data[2:2 + n]]
best = None
for mask in range(1 << n):
    s = 0
    losses = 0
    for i in range(n):
        if mask >> i & 1:
            s += a[i]
            if a[i] < 0:
                losses += 1
    if losses >= k and (best is None or s > best):
        best = s
print(-1 if best is None else best)

